```javascript
/*You are given a word. Your task is to find the closest vowel that stands between 
  two consonants from the right side of the word (case sensitive).

  Vowels in the beginning and ending doesn't count. Return empty string if you didn't
  find any vowel met the above condition. 

  You may assume that the given string contains English letter only.

  Example:
  getClosestVowel("yogurt") ==> "u"
  getClosestVowel("FULL") ==> "U"
  getClosestVowel("quick") ==> ""
  getClosestVowel("ab") ==> ""
  */
const getClosestVowel = (word) => {
  const vowels = "aeiouAEIOU";

  // Helper function to check if a character is a vowel
  const isVowel = (char) => vowels.includes(char);

  // Helper function to check if a character is a consonant
  // Since the input is guaranteed to be English letters only, 
  // anything that isn't a vowel is a consonant.
  const isConsonant = (char) => !isVowel(char);

  // We iterate from the right side of the word.
  // We start at index length - 2 and end at index 1 because 
  // vowels at the beginning (0) and ending (length - 1) don't count.
  for (let i = word.length - 2; i >= 1; i--) {
    const currentChar = word[i];
    const prevChar = word[i - 1];
    const nextChar = word[i + 1];

    // Check if current character is a vowel and is surrounded by consonants
    if (isVowel(currentChar) && isConsonant(prevChar) && isConsonant(nextChar)) {
      return currentChar;
    }
  }

  // Return empty string if no such vowel is found
  return "";
};
```

