import java.util.*;
import java.lang.*;

class Solution {
    /**
    Given an array of integers nums, find the minimum sum of any non-empty sub-array
    of nums.
    Example
    minSubArraySum(Arrays.asList(2, 3, 4, 1, 2, 4)) == 1
    minSubArraySum(Arrays.asList(-1, -2, -3)) == -6
     */
    public int minSubArraySum(List<Integer> nums) {
        if (nums == null || nums.isEmpty()) {
            throw new IllegalArgumentException("Input list must not be empty");
        }

        // This is a variation of Kadane's Algorithm.
        // Instead of finding the maximum subarray sum, we track the minimum.
        int minSoFar = nums.get(0);
        int currentMin = nums.get(0);

        for (int i = 1; i < nums.size(); i++) {
            int num = nums.get(i);

            // At each element, we decide: 
            // Should we start a new subarray here, or extend the existing minimum subarray?
            currentMin = Math.min(num, currentMin + num);

            // Update the global minimum found across all subarrays
            minSoFar = Math.min(minSoFar, currentMin);
        }

        return minSoFar;
    }
}
