// isVowel is a helper function to check if a byte is an English vowel.
func isVowel(b byte) bool {
	return bytes.ContainsAny([]byte{b}, "aeiouAEIOU")
}

// isConsonant is a helper function to check if a byte is an English consonant.
// Since the problem assumes the string contains English letters only, 
// any letter that isn't a vowel is a consonant.
func isConsonant(b byte) bool {
	return !isVowel(b)
