// GetClosestVowel finds the closest vowel that stands between
// two consonants from the right side of the word (case sensitive).
func GetClosestVowel(word string) string {
	n := len(word)
	// A vowel between two consonants requires at least 3 characters.
	if n < 3 {
		return ""
	}

	// We iterate from right to left to find the "closest" vowel to the right side.
	// Vowels at the beginning (index 0) and ending (index n-1) don't count,
	// so we start at n-2 and end at 1.
	for i := n - 2; i >= 1; i-- {
		if isVowel(word[i]) {
			// Check if the characters to the left and right are both consonants.
			if isConsonant(word[i-1]) && isConsonant(word[i+1]) {
				return string(word[i])
			}
		}
	}

	return ""
}
