```javascript
/*Task
  We are given two strings s and c, you have to deleted all the characters in s that are equal to any character in c
  then check if the result string is palindrome.
  A string is called palindrome if it reads the same backward as forward.
  You should return a tuple containing the result string and true/false for the check.
  Example
  For s = "abcde", c = "ae", the result should be ('bcd',false)
  For s = "abcdef", c = "b"  the result should be ('acdef',false)
  For s = "abcdedcba", c = "ab", the result should be ('cdedc',true)
  */
const reverseDelete = (s, c) => {
  // 1. Filter the string s: keep characters that are NOT included in string c
  const resultString = s
    .split('')
    .filter(char => !c.includes(char))
    .join('');

  // 2. Check if the resultString is a palindrome
  // We reverse the string and compare it to the original resultString
  const reversedString = resultString.split('').reverse().join('');
  const isPalindrome = resultString === reversedString;

  // 3. Return as a tuple (represented as an array in JavaScript)
  return [resultString, isPalindrome];
};

// Test Cases
console.log(reverseDelete("abcde", "ae"));      // ['bcd', false]
