// FixSpaces replaces all spaces in the text with underscores.
// If there are more than 2 consecutive spaces, they are replaced by a single hyphen.
func FixSpaces(text string) string {
	var result strings.Builder
	n := len(text)

	for i := 0; i < n; {
		if text[i] == ' ' {
			// Count consecutive spaces
			count := 0
			for i < n && text[i] == ' ' {
				count++
				i++
			}

			if count > 2 {
				// More than 2 consecutive spaces are replaced by a single '-'
				result.WriteByte('-')
			} else {
				// 1 or 2 spaces are replaced by underscores (1:1 mapping)
				for j := 0; j < count; j++ {
					result.WriteByte('_')
				}
			}
		} else {
			// Append non-space characters as they are
			result.WriteByte(text[i])
			i++
		}
	}

	return result.String()
}
