// Perform binary XOR on these inputs and return result also as a string.
// >>> StringXor('010', '110')
// '100'
func StringXor(a string, b string) string {
    // Create a byte slice to hold the result for efficiency
    result := make([]byte, len(a))

    for i := 0; i < len(a); i++ {
        // If the characters are the same, XOR result is '0'
        // If the characters are different, XOR result is '1'
        if a[i] == b[i] {
            result[i] = '0'
        } else {
            result[i] = '1'
        }
    }

    return string(result)
}
