        }
        ViewUserVO viewUserVO = new ViewUserVO();
        BeanUtils.copyProperties(userDO, viewUserVO);
        if (Objects.nonNull(userDO.getBirthday())) {
            viewUserVO.setBirthday(userDO.getBirthday().toString());
        }
        Integer attentionNum = userAttentionMapper.getCountById(userDO.getId());
        Integer fansNum = userFansMapper.getCountById(userDO.getId());
        viewUserVO.setAttentionNum(attentionNum != null ? attentionNum : 0);
        viewUserVO.setFansNum(fansNum != null ? fansNum : 0);

        // Check if current user is following the target user
        // Note: This requires the current logged-in user ID, which usually comes from a ThreadLocal/SecurityContext
        // For the sake of this implementation, we assume a mechanism to get currentUserId or leave it as 0/null
        return ResultUtil.successGet("获取用户信息成功", viewUserVO);
    }
